// Impure: Mutates external state & relies on hidden time dependency
let requestCount = 0;
function logImpure(article: Article) {
  requestCount++;
  article.views = (article.views || 0) + 1;
  console.log(`Visited at ${Date.now()}`);
}

// Pure: Deterministic, immutable, and trivially testable
function computeWordCount(article: Readonly<Article>): number {
  return article.body.reduce((total, block) => {
    if (block.type === 'p' || block.type === 'quote') {
      return total + block.text.trim().split(/\s+/).length;
    }
    return total;
  }, 0);
}
